import React, { useState, useEffect } from 'react';
import { getEvolutions, createEvolution, updateEvolution, deleteEvolution, getPatients } from '../services/api';
import './Pages.css';

export default function Evolution() {
  const [evolutions, setEvolutions] = useState([]);
  const [patients, setPatients] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [showModal, setShowModal] = useState(false);
  const [selectedEvolution, setSelectedEvolution] = useState(null);
  const [editing, setEditing] = useState(null);
  const [form, setForm] = useState({
    patientId: '',
    professionalName: '',
    status: 'active',
    notes: '',
    evolutionDate: ''
  });

  useEffect(() => {
    fetchEvolutions();
    fetchPatients();
  }, []);

  const fetchEvolutions = async () => {
    try {
      const res = await getEvolutions();
      setEvolutions(res.data);
    } catch (err) {
      console.error('Error:', err);
    }
  };

  const fetchPatients = async () => {
    try {
      const res = await getPatients();
      setPatients(res.data);
    } catch (err) {
      console.error('Error:', err);
    }
  };

  const resetForm = () => {
    setEditing(null);
    setForm({
      patientId: '',
      professionalName: '',
      status: 'active',
      notes: '',
      evolutionDate: ''
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      if (editing) {
        await updateEvolution(editing, form);
      } else {
        await createEvolution(form);
      }
      resetForm();
      setShowForm(false);
      fetchEvolutions();
    } catch (err) {
      console.error('Error:', err);
    }
  };

  const handleEdit = (item) => {
    setEditing(item.id);
    setForm({
      patientId: item.patientId,
      professionalName: item.professionalName,
      status: item.status,
      notes: item.notes,
      evolutionDate: item.evolutionDate
    });
    setShowForm(true);
  };

  const handleViewEvolution = (item) => {
    setSelectedEvolution(item);
    setShowModal(true);
  };

  const closeModal = () => {
    setShowModal(false);
    setSelectedEvolution(null);
  };

  const handleDelete = async (id) => {
    if (window.confirm('¿Eliminar esta evolución clínica?')) {
      try {
        await deleteEvolution(id);
        fetchEvolutions();
      } catch (err) {
        console.error('Error:', err);
      }
    }
  };

  return (
    <div className="page">
      <div className="page-header">
        <h2>📋 Evolución Clínica</h2>
        <button onClick={() => { resetForm(); setShowForm(!showForm); }} className="btn-primary">
          {showForm ? 'Cancelar' : editing ? 'Editar Evolución' : '+ Nueva Evolución'}
        </button>
      </div>

      {showForm && (
        <form onSubmit={handleSubmit} className="form-container">
          <select
            value={form.patientId}
            onChange={(e) => setForm({ ...form, patientId: e.target.value })}
            required
          >
            <option value="">Selecciona paciente</option>
            {patients.map((p) => (
              <option key={p.id} value={p.id}>{p.firstName} {p.lastName}</option>
            ))}
          </select>
          <input
            type="text"
            placeholder="Profesional"
            value={form.professionalName}
            onChange={(e) => setForm({ ...form, professionalName: e.target.value })}
          />
          <select
            value={form.status}
            onChange={(e) => setForm({ ...form, status: e.target.value })}
          >
            <option value="active">Activo</option>
            <option value="review">En revisión</option>
            <option value="completed">Completado</option>
          </select>
          <input
            type="date"
            value={form.evolutionDate}
            onChange={(e) => setForm({ ...form, evolutionDate: e.target.value })}
            required
          />
          <textarea
            placeholder="Notas clínicas"
            value={form.notes}
            onChange={(e) => setForm({ ...form, notes: e.target.value })}
          />
          <button type="submit" className="btn-success">
            {editing ? 'Actualizar' : 'Guardar'}
          </button>
        </form>
      )}

      <table className="table">
        <thead>
          <tr>
            <th>Fecha</th>
            <th>Paciente</th>
            <th>Profesional</th>
            <th>Estado</th>
            <th>Notas</th>
            <th>Acciones</th>
          </tr>
        </thead>
        <tbody>
          {evolutions.map((item) => (
            <tr key={item.id}>
              <td>{new Date(item.evolutionDate).toLocaleDateString()}</td>
              <td>{item.patientFirstName} {item.patientLastName}</td>
              <td>{item.professionalName || '-'}</td>
              <td>{item.status}</td>
              <td>{item.notes?.slice(0, 64)}</td>
              <td>
                <button className="btn-primary" onClick={() => handleEdit(item)}>Editar</button>
                <button className="btn-danger" onClick={() => handleDelete(item.id)}>Eliminar</button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
